import pygame
from constants import *

class Enemy:
    def __init__(self, x, y, patrol_range=120):
        self.x = x
        self.y = y
        self.w = 30
        self.h = 30
        self.start_x = x
        self.vx = -1.5
        self.vy = 0
        self.alive = True
        self.frame = 0
        self.patrol_range = patrol_range
        self.squish_timer = 0

    def update(self, solids):
        if not self.alive:
            self.squish_timer -= 1
            return

        self.vy += GRAVITY
        if self.vy > 10:
            self.vy = 10

        self.x += self.vx
        self.y += self.vy

        # 巡逻范围
        if abs(self.x - self.start_x) > self.patrol_range:
            self.vx = -self.vx

        # 地面碰撞
        rect = pygame.Rect(self.x, self.y, self.w, self.h)
        for s in solids:
            if rect.colliderect(s):
                if self.vy > 0:
                    self.y = s.top - self.h
                    self.vy = 0
                elif self.vx > 0:
                    self.x = s.left - self.w
                    self.vx = -self.vx
                elif self.vx < 0:
                    self.x = s.right
                    self.vx = -self.vx
                rect = pygame.Rect(self.x, self.y, self.w, self.h)

        # 边缘检测：前方地面消失则转向
        self._edge_detect(solids)

        # 掉落
        if self.y > SCREEN_H + 100:
            self.alive = False

        self.frame += 1

    def _edge_detect(self, solids):
        """检测前方是否有地面，无则转向"""
        check_x = self.x + (self.w + 2 if self.vx > 0 else -2)
        check_y = self.y + self.h + 2
        probe = pygame.Rect(check_x, check_y, 4, 4)
        on_edge = True
        for s in solids:
            if probe.colliderect(s):
                on_edge = False
                break
        if on_edge:
            self.vx = -self.vx

    def squish(self):
        self.alive = False
        self.squish_timer = 20
        self.h = 10

    def draw(self, surface, cam_x):
        if self.squish_timer <= 0 and not self.alive:
            return
        sx = self.x - cam_x
        # 绘制裁剪
        if sx < -self.w or sx > SCREEN_W + self.w:
            return
        if self.alive:
            from sprites import draw_goomba
            draw_goomba(surface, sx, self.y, self.w, self.h, self.frame)
        else:
            pygame.draw.ellipse(surface, (150, 50, 50), (sx, self.y, self.w, self.h))

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

import pygame
from constants import *

class Camera:
    def __init__(self, level_width):
        self.x = 0.0
        self.target_x = 0.0
        self.level_width = level_width

    def update(self, target_x):
        self.target_x = target_x - SCREEN_W // 3
        self.target_x = max(0, min(self.target_x, self.level_width - SCREEN_W))
        # 平滑跟随
        self.x += (self.target_x - self.x) * CAMERA_SMOOTHING

    def apply(self, x):
        return x - int(self.x)

import pygame
import math
from constants import *
from sprites import draw_coin

class Coin:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.w = 20
        self.h = 24
        self.collected = False
        self.frame = 0

    def update(self):
        self.frame += 1

    def draw(self, surface, cam_x):
        if self.collected:
            return
        sx = self.x - cam_x
        if sx < -self.w or sx > SCREEN_W + self.w:
            return
        draw_coin(surface, sx, self.y, self.w, self.h, self.frame)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

class Flag:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.w = 10
        self.h = TILE * 4
        self.reached = False

    def draw(self, surface, cam_x):
        sx = self.x - cam_x
        if sx < -50 or sx > SCREEN_W + 50:
            return
        # 旗杆
        pygame.draw.rect(surface, POLE_COLOR, (sx, self.y, self.w, self.h))
        # 旗帜
        flag_y = self.y + 10
        points = [(sx + self.w, flag_y), (sx + self.w + 30, flag_y + 15), (sx + self.w, flag_y + 30)]
        color = (255, 50, 50) if not self.reached else (50, 255, 50)
        pygame.draw.polygon(surface, color, points)
        # 顶部球
        pygame.draw.circle(surface, YELLOW, (sx + self.w // 2, self.y), 6)

    def get_rect(self):
        return pygame.Rect(self.x, self.y, self.w + 30, self.h)
